# here must be individually detectable by ``find_tracked_packages`` when it
# appears in a dependency file.
TRACKED_PACKAGES: frozenset[str] = frozenset({"google-adk"})

# Never read more than roughly 5 MB from any single dependency file. Anything
# beyond the cap is silently discarded rather than raising.
_MAX_BYTES = 5 * 1024 * 1024

# Files inspected inside each dependency directory, in precedence order.
_DEPENDENCY_FILES = ("uv.lock", "pyproject.toml", "requirements.txt")


def find_tracked_packages(config: pathlib.Path, config_json: dict) -> list[str]:
    """Scan declared dependency directories for tracked packages.

    Args:
        config: Path to the `langgraph.json` config file. Its parent directory
            is treated as the project root; dependency paths are resolved
            relative to it and paths escaping the root are skipped.
        config_json: The parsed config contents. Dependency directory paths are
            read from `config_json["dependencies"]`; non-string entries are
            ignored.

    Returns:
        A list of `"package_name:version_specifier"` strings for the first
        dependency path that contains at least one tracked package, or an empty
        list if none of the scanned files reference a tracked package.
    """
    root = config.resolve().parent
    dependencies = config_json.get("dependencies") or []

    for dep in dependencies:
        if not isinstance(dep, str):
            # Silently ignore malformed entries (ints, None, ...).
            continue

        resolved = (root / dep).resolve()
        # Skip anything that resolves outside the project root.
        if resolved != root and root not in resolved.parents:
            continue

        matches = _scan_directory(resolved)
        if matches:
            # Return results from the first dependency path that has a match,
            # ordered deterministically by the tracked-package list.
            return [
                f"{pkg}:{matches[pkg]}"
                for pkg in TRACKED_PACKAGES
                if pkg in matches
            ]

    return []


def _scan_directory(directory: pathlib.Path) -> dict[str, str]:
    """Return tracked packages found in a single dependency directory.

    The first dependency file (in precedence order) that yields any match wins;
    remaining files are not consulted.
    """
    for filename in _DEPENDENCY_FILES:
        path = directory / filename
        if not path.is_file():
            continue
        content = _read_capped(path)
        if content is None:
            continue
        if filename == "uv.lock":
            matches = _parse_uv_lock(content)
        elif filename == "pyproject.toml":
            matches = _parse_pyproject(content)
        else:
            matches = _parse_requirements(content)
        if matches:
            return matches
    return {}


def _read_capped(path: pathlib.Path) -> str | None:
    """Read up to `_MAX_BYTES` from `path`, decoding leniently.

    Content beyond the cap is discarded. Returns None if the file cannot be
    read.
    """
    try:
        with open(path, "rb") as f:
            data = f.read(_MAX_BYTES)
    except OSError:
        return None
    return data.decode("utf-8", errors="replace")


